words={'疲惫不堪':'十分疲乏，难以支撑。','疲惫':'非常疲乏。','闷闷不乐':'因心事而不高兴。','安慰':'用话语或行动使难过的人好受些。','打扰':'影响别人休息或做事。','苦恼':'因困难而烦闷、不知道怎么办。','贴心':'能体会别人的心情和需要。','欣慰':'感到安慰和高兴。','犹豫':'拿不定主意。','打气':'鼓励别人，给人信心。','拥抱':'用双臂抱住别人。','不分青红皂白':'不弄清事情的缘由就作出判断。','教训':'这里指责备。','顶嘴':'用话反驳长辈的责备；课文中是妈妈对解释的看法。','叛逆':'不愿顺从，反抗原有的要求；文中是妈妈对美华的评价。','委屈':'受到不应有的指责而心里难过。','体谅':'设身处地理解别人的处境和心情。','刀子嘴，豆腐心':'说话尖刻，但心地柔软。','内疚':'内心觉得有亏欠而惭愧。','不妨':'表示可以试一试。','匿名':'不写出姓名。','允许':'答应、准许。','监督':'查看别人是否按要求去做。','窒息':'基本义是呼吸困难甚至停止；文中形容受到限制时的压抑感。','代沟':'不同世代在想法、习惯等方面的差异，造成理解和沟通困难。','无可厚非':'不能过分责备；这里指喜欢游戏、从中得到乐趣本身。','上瘾':'对某事过度依赖，很难停止。','无心':'没有心思去做某事。','疏远':'关系不如以前亲近。','限制':'规定不能超过的范围。','设身处地':'把自己放在对方的处境来想。','迎刃而解':'比喻关键问题解决后，其他相关问题就容易解决。'}
lex={w.replace('，',''):dict(meaning=m,en='') for w,m in words.items()}
(D/'lexicon.js').write_text('window.LESSON_WORDS = '+json.dumps(lex,ensure_ascii=False,indent=2)+';\nwindow.WORD_ALIASES={"刀子嘴，豆腐心":"刀子嘴豆腐心"};\nwindow.HWT_WORD_CONTEXT=()=>({lessonId:window.LESSON.id,lessonTitle:window.LESSON.title,grade:2,unit:1,paragraphs:window.LESSON.paragraphs});\nwindow.HWT_WORD_LEXICON=()=>window.LESSON_WORDS;\n')
print('Created six messages, eight tasks and',len(words),'context words')
